                    height: 48,
                    child: Toggle(
                      onColor: colors.popupBG,
                      onText: PrivacyNetwork.tor.label,
                      offColor: colors.textFieldDefaultBG,
                      offText: PrivacyNetwork.nym.label,
                      isOn: _shown == PrivacyNetwork.nym,
                      onValueChanged: (nym) => setState(() {
                        _shown = nym ? PrivacyNetwork.nym : PrivacyNetwork.tor;
                      }),
                      decoration: BoxDecoration(
                        color: Colors.transparent,
                        borderRadius: BorderRadius.circular(
                          Constants.size.circularBorderRadius,
