                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

/// The animation's width: as the onion's.
double _animationWidth(BuildContext context) {
  final size = MediaQuery.sizeOf(context);
  return ScreenFit.sideBySide(context)
      ? min(size.height - 230, 320.0)
      : min(size.width, ScreenFit.columnWidth) / 1.5;
}

