            ),
            const _CapsText(network: PrivacyNetwork.nym),
          ],
        ),
      ),
    );
  }
}

class _TorAnimatedButton extends ConsumerStatefulWidget {
  const _TorAnimatedButton();

  @override
  ConsumerState<_TorAnimatedButton> createState() => _TorAnimatedButtonState();
}

class _TorAnimatedButtonState extends ConsumerState<_TorAnimatedButton>
    with SingleTickerProviderStateMixin {
  late final AnimationController controller1;

  late TorConnectionStatus _status;

  Future<void> onTap() => tapNetwork(ref, context, PrivacyNetwork.tor, _status);

  Future<void> _playPlug() async {
    await _play(from: "0.0", to: "connecting-start", repeat: false);
  }

  Future<void> _playConnecting({double? start}) async {
    await _play(
      from: start?.toString() ?? "connecting-start",
      to: "connecting-end",
      repeat: true,
    );
  }

  Future<void> _playConnectingDone() async {
    await _play(
      from: "${controller1.value}",
      to: "connected-start",
      repeat: false,
    );
  }

  Future<void> _playConnected() async {
    await _play(from: "connected-start", to: "connected-end", repeat: true);
  }

  Future<void> _playDisconnect() async {
    await _play(
      from: "disconnection-start",
      to: "disconnection-end",
      repeat: false,
    );
    controller1.reset();
  }

  Future<void> _play({
    required String from,
    required String to,
    required bool repeat,
  }) async {
    final composition = await _completer.future;
    final start = double.tryParse(from) ?? composition.getMarker(from)!.start;
    final end = composition.getMarker(to)!.start;

    controller1.value = start;

    if (repeat) {
      await controller1.repeat(
        min: start,
        max: end,
        period: composition.duration * (end - start),
      );
    } else {
      await controller1.animateTo(
        end,
        duration: composition.duration * (end - start),
      );
    }
  }

  late Completer<LottieComposition> _completer;

  @override
  void initState() {
    controller1 = AnimationController(vsync: this);

    _status = ref.read(pTorService).status;

    _completer = Completer();

    super.initState();
  }

  @override
  void dispose() {
    controller1.dispose();

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final width = _animationWidth(context);

    return TorSubscription(
      onTorStatusChanged: (status) async {
        _status = status;
        switch (_status) {
          case TorConnectionStatus.disconnected:
            await _playDisconnect();
            break;

          case TorConnectionStatus.connected:
            await _playConnectingDone();
            await _playConnected();
            break;

          case TorConnectionStatus.connecting:
            await _playPlug();
            await _playConnecting();
            break;
        }
      },
      child: ConditionalParent(
        // Tappable while connecting too, to cancel.
        condition: true,
        builder: (child) => GestureDetector(onTap: onTap, child: child),
        child: Column(
          children: [
            SizedBox(
              width: width,
              child: Lottie.asset(
                Assets.lottie.onionTor,
                controller: controller1,
                width: width,
                // height: width,
                onLoaded: (composition) {
                  _completer.complete(composition);
                  controller1.duration = composition.duration;

                  if (_status == TorConnectionStatus.connected) {
                    _playConnected();
                  } else if (_status == TorConnectionStatus.connecting) {
                    _playConnecting();
                  }
                },
              ),
            ),
            const _CapsText(network: PrivacyNetwork.tor),
          ],
        ),
      ),
    );
  }
}

/// The network's status, and under it the button that connects,
/// cancels or disconnects it.
class _StatusButton extends StatelessWidget {
  const _StatusButton({required this.network});

  final PrivacyNetwork network;

  String _label(TorConnectionStatus status) => switch (status) {
    TorConnectionStatus.disconnected => l10n.commonDisconnected,
    TorConnectionStatus.connected => l10n.commonConnected,
    TorConnectionStatus.connecting => l10n.commonConnecting,
  };

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).extension<StackColors>()!;
    return NetworkStatusBuilder(
      network: network,
      builder: (context, _, status) => Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          RoundedWhiteContainer(
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 8.0),
              child: Row(
                children: [
                  Text(
                    network == PrivacyNetwork.tor
                        ? l10n.torStatus
                        : l10n.nymStatus,
                    style: STextStyles.titleBold12(context),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Text(
                      _label(status),
                      textAlign: TextAlign.end,
                      style: STextStyles.itemSubtitle(context)
                          .copyWith(color: networkStatusColor(status, colors)),
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 8),
          NetworkActionButton(
            network: network,
            status: status,
            width: double.infinity,
          ),
        ],
      ),
    );
  }
}

class _CapsText extends ConsumerWidget {
  const _CapsText({required this.network});

  final PrivacyNetwork network;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    // With the other network on, a tap switches over.
    final active = ref.watch(
      prefsChangeNotifierProvider.select(NetworkPrivacy.activeIn),
    );
    final switching = active != null && active != network;
    return NetworkStatusBuilder(
      network: network,
      builder: (context, _, status) => Text(
        switch (status) {
          TorConnectionStatus.disconnected when switching =>
            l10n.networkSwitchCaps(network.label),
          TorConnectionStatus.disconnected => l10n.torConnectCaps,
          TorConnectionStatus.connected => l10n.torStopCaps,
          TorConnectionStatus.connecting => l10n.torConnectingCaps,
        },
        textAlign: TextAlign.center,
        style: STextStyles.pageTitleH2(context).copyWith(
          color: networkStatusColor(
            status,
            Theme.of(context).extension<StackColors>()!,
          ),
        ),
      ),
    );
  }
}
